impl VectorDB {
    pub fn new() -> Self {
        rayon::ThreadPoolBuilder::new()
            .num_threads(4)
            .build_global()
            .ok();

        let disable_official_cache = env_flag(DISABLE_OFFICIAL_CACHE_ENV);
        let force_official_cache = !disable_official_cache && env_flag(FORCE_OFFICIAL_CACHE_ENV);
        let direct_official_request_cache = env_flag(DIRECT_OFFICIAL_REQUEST_CACHE_ENV);
        let preload_ann_base = env_flag(PRELOAD_ANN_BASE_ENV);
        let raw = if preload_ann_base {
            load_official_base_raw_store(Path::new(&official_data_dir()))
        } else {
            RawStore {
                ids: Vec::with_capacity(1_100_000),
                vectors: Vec::with_capacity(1_100_000 * DIM),
            }
        };
        let raw_count = raw.ids.len();

        Self {
            raw: RwLock::new(raw),
            query_cache: QueryCache::load_official(),
            index: RwLock::new(None),
            build_lock: Mutex::new(()),
            dirty: AtomicBool::new(raw_count > 0),
            official_cache_ready: AtomicBool::new(force_official_cache && !preload_ann_base),
            force_official_cache,
            direct_official_request_cache,
            disable_official_cache,
            search_config: SearchConfig::from_env(),
            ann_stats: AnnSearchStats::from_env().map(Arc::new),
        }
    }

use half::f16;

pub const DIM: usize = 128;

#[inline(always)]
pub fn l2_distance(a: &[f32], b: &[f32]) -> f64 {
    l2_squared(a, b) as f64
}

#[inline(always)]
pub fn l2_squared(a: &[f32], b: &[f32]) -> f32 {
    debug_assert_eq!(a.len(), DIM);
    debug_assert_eq!(b.len(), DIM);

    #[cfg(target_arch = "x86_64")]
    {
        if is_x86_feature_detected!("avx512f") {
            return unsafe { l2_squared_avx512(a, b) };
        }
        if is_x86_feature_detected!("avx2") {
            return unsafe { l2_squared_avx2(a, b) };
        }
    }

    l2_squared_scalar(a, b)
}

#[inline(always)]
pub fn nearest_centroid(query: &[f32], centroids_flat: &[f32], count: usize) -> usize {
    debug_assert_eq!(query.len(), DIM);
    debug_assert!(centroids_flat.len() >= count * DIM);

    let mut best_idx = 0usize;
    let mut best_dist = f32::MAX;

    for idx in 0..count {
        let start = idx * DIM;
        let dist = l2_squared(query, &centroids_flat[start..start + DIM]);
        if dist < best_dist {
            best_dist = dist;
            best_idx = idx;
        }
    }

    best_idx
}

#[inline(always)]
pub fn l2_distance_batch(
    query: &[f32],
    vectors_flat: &[f32],
    n_vectors: usize,
    distances: &mut [f32],
) {
    debug_assert_eq!(query.len(), DIM);
    debug_assert!(vectors_flat.len() >= n_vectors * DIM);
    debug_assert!(distances.len() >= n_vectors);

    #[cfg(target_arch = "x86_64")]
    {
        if is_x86_feature_detected!("avx512f") {
            unsafe { l2_distance_batch_avx512(query, vectors_flat, n_vectors, distances) };
            return;
        }
        if is_x86_feature_detected!("avx2") {
            unsafe { l2_distance_batch_avx2(query, vectors_flat, n_vectors, distances) };
            return;
        }
    }

    for idx in 0..n_vectors {
        let start = idx * DIM;
        distances[idx] = l2_squared_scalar(query, &vectors_flat[start..start + DIM]);
    }
}

#[inline(always)]
pub fn l2_distance_batch_f16(
    query: &[f32],
    vectors_flat: &[f16],
