            return None;
        }

        raw.ids.push(idx as u64);
        let vector_bytes = &bytes[record_start + 4..record_start + record_len];
        for chunk in vector_bytes.chunks_exact(4) {
            raw.vectors
                .push(f32::from_le_bytes(chunk.try_into().ok()?));
        }
    }

